class Address:
    def __init__(self, street, city, zip_code):
        self.street = street
        self.city = city
        self.zip_code = zip_code


class Person:
    def __init__(self, name, age, address):
        self.name = name
        self.age = age
        self.address = address

    def summary(self):
        return f"{self.name}, age {self.age}, {self.address.city}"


class Roster:
    def __init__(self, name):
        self.name = name
        self.people = []

    def add_person(self, person):
        self.people.append(person)

    def find_by_city(self, city):
        return [p for p in self.people if p.address.city == city]
